import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        int n = s.length();
        int minDiff = Integer.MAX_VALUE;

        // Try all possible first split positions
        for (int i = 1; i < n; i++) {
            // Try all possible second split positions
            for (int j = i + 1; j < n; j++) {
                int a = Integer.parseInt(s.substring(0, i));
                int b = Integer.parseInt(s.substring(i, j));
                int c = Integer.parseInt(s.substring(j));

                int maxVal = Math.max(a, Math.max(b, c));
                int minVal = Math.min(a, Math.min(b, c));
                int diff = maxVal - minVal;
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        System.out.println(minDiff);
    }
}

