public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            System.out.println(solve(line));
        }
    }

    static long solve(String s) {
        int n = s.length();
        long minDiff = Long.MAX_VALUE;

        // Try all possible splits (at least 2 segments)
        // 2^(n-1) subsets of split positions
        for (int mask = 1; mask < (1 << (n-1)); mask++) {
            List<Long> segments = new ArrayList<>();
            int start = 0;
            for (int i = 0; i < n-1; i++) {
                if ((mask & (1 << i)) != 0) {
                    segments.add(Long.parseLong(s.substring(start, i+1)));
                    start = i+1;
                }
            }
            segments.add(Long.parseLong(s.substring(start)));

            long maxVal = Collections.max(segments);
            long minVal = Collections.min(segments);
            minDiff = Math.min(minDiff, maxVal - minVal);
        }

        return minDiff;
    }
}

