        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        s = s.trim();

        int n = s.length();
        if (n == 0) {
            System.out.println(0);
            return;
        }

        // Interpret the task as:
        // Split the string into two non-empty parts, convert each part to integers,
        // and minimize the absolute difference between the two values.
        //
        // Since values may be large, use BigInteger.
        java.math.BigInteger best = null;

        for (int i = 1; i < n; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);

            java.math.BigInteger a = new java.math.BigInteger(left);
            java.math.BigInteger b = new java.math.BigInteger(right);
            java.math.BigInteger diff = a.subtract(b).abs();

            if (best == null || diff.compareTo(best) < 0) {
                best = diff;
            }
        }

        System.out.println(best == null ? 0 : best.toString());
    }
}

