#define MAX_LEN 100005

// Helper function to compute integer value of substring s[l..r] (inclusive)
long long substring_value(char *s, int l, int r) {
    long long val = 0;
    for (int i = l; i <= r; i++) {
        val = val * 10 + (s[i] - '0');
    }
    return val;
}

int main() {
    char s[MAX_LEN];
    scanf("%s", s);
    int n = strlen(s);

    // dp[i] = minimal possible difference for prefix ending at i-1
    // We'll store both min_val and max_val for each partition ending at i
    long long min_val[1005], max_val[1005];
    int dp[1005];

    // Initialize dp with large values
    for (int i = 0; i <= n; i++) {
        dp[i] = INT_MAX;
        min_val[i] = LLONG_MAX;
        max_val[i] = LLONG_MIN;
    }

    // Base case: empty prefix
    dp[0] = 0;
    min_val[0] = LLONG_MAX; // no segments yet
    max_val[0] = LLONG_MIN;

    // dp[i] corresponds to prefix of length i (first i characters)
    for (int i = 1; i <= n; i++) {
        // Try all possible last segment s[j..i-1]
        for (int j = 0; j < i; j++) {
            if (dp[j] == INT_MAX) continue;

            long long seg_val = substring_value(s, j, i-1);

            // Compute new min and max for this partition
            long long new_min = seg_val;
            long long new_max = seg_val;

            if (j > 0) {
                new_min = (min_val[j] < seg_val) ? min_val[j] : seg_val;
                new_max = (max_val[j] > seg_val) ? max_val[j] : seg_val;
            }

            long long diff = new_max - new_min;

            if (diff < dp[i] || (diff == dp[i] && new_min < min_val[i])) {
                dp[i] = diff;
                min_val[i] = new_min;
                max_val[i] = new_max;
            }
        }
    }

    printf("%lld\n", dp[n]);
    return 0;
}

