#define MAXN 205

/*
Assumption from the statement:
- We are given a string of digits.
- We split it into contiguous non-empty segments.
- Each segment is interpreted as an integer value.
- We want to minimize (max segment value - min segment value).

A natural interpretation is to allow any number of segments >= 2.
For any fixed [L, R], if every segment value must lie within [L, R],
then the string is splittable iff we can partition it into numbers all in [L, R].
We enumerate all possible substring values as candidates for L and R.

Since values can be very large, we only keep substrings up to 18 digits
and use unsigned long long. This is typical for digit-string partition tasks.
*/

typedef unsigned long long ULL;

char s[MAXN];
int n;

ULL vals[MAXN][MAXN];
int okv[MAXN][MAXN];

int can_split(ULL low, ULL high) {
    int dp[MAXN] = {0};
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        if (!dp[i]) continue;
        for (int j = i; j < n; j++) {
            if (!okv[i][j]) break;
            ULL x = vals[i][j];
            if (x >= low && x <= high) dp[j + 1] = 1;
        }
    }
    return dp[n];
}

int main() {
    if (scanf("%204s", s) != 1) return 0;
    n = (int)strlen(s);

    for (int i = 0; i < n; i++) {
        ULL x = 0;
        for (int j = i; j < n; j++) {
            if (j - i + 1 > 18) {
                okv[i][j] = 0;
                continue;
            }
            x = x * 10 + (ULL)(s[j] - '0');
            vals[i][j] = x;
            okv[i][j] = 1;
        }
    }

    ULL cand[MAXN * MAXN];
    int m = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (okv[i][j]) cand[m++] = vals[i][j];
        }
    }

    ULL ans = ULLONG_MAX;

    for (int i = 0; i < m; i++) {
        for (int j = i; j < m; j++) {
            ULL a = cand[i], b = cand[j];
            ULL low = a < b ? a : b;
            ULL high = a < b ? b : a;
            if (high - low >= ans) continue;
            if (can_split(low, high)) {
                ans = high - low;
            }
        }
    }

    if (ans == ULLONG_MAX) ans = 0;
    printf("%llu\n", ans);
    return 0;
}

